mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.25) * p.xz;
  p.yz = rot(0.5) * p.yz;
  vec2 q = vec2(length(p.xz) - 1.6, p.y);
  float tor = length(q) - 0.38;
  float ribs = abs(sin(atan(p.z, p.x) * 16.0)) * 0.07;
  return tor - ribs;
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.8);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 8.0) break;
    t += d * 0.8;
  }
  vec3 col = glow * vec3(0.2, 0.8, 1.1) * (0.8 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
